package com.lacuna.mod.registry;

import com.lacuna.mod.Lacuna;
import net.minecraft.core.registries.Registries;
import net.minecraft.sounds.SoundEvent;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;

/** Custom sound events (files and subtitles in assets/lacuna/sounds.json, generated by tools/content/m13_fx.py). */
public final class ModSounds {
    public static final DeferredRegister<SoundEvent> SOUNDS = DeferredRegister.create(Registries.SOUND_EVENT, Lacuna.MODID);

    /** The Totem of Banishing's toll, rung on every use. */
    public static final DeferredHolder<SoundEvent, SoundEvent> TOTEM_BELL = SOUNDS.register("item.totem_of_banishing.bell",
            () -> SoundEvent.createVariableRangeEvent(Lacuna.id("item.totem_of_banishing.bell")));

    private ModSounds() {}
}
